import React, { useRef, useEffect, useState, useCallback } from 'react';
import './InteractiveChart.css';

interface ChartDataPoint {
  date: string;
  daily_pnl: number;
  cumulative_pnl: number;
  entry_time?: string;
  account?: string;
  time_slot?: string;
}

interface InteractiveChartProps {
  data: ChartDataPoint[];
  formatCurrency: (value: number) => string;
  width?: number;
  height?: number;
}

const InteractiveChart: React.FC<InteractiveChartProps> = ({
  data,
  formatCurrency,
  width = 1200,
  height = 400
}) => {
  const svgRef = useRef<SVGSVGElement>(null);
  const [zoom, setZoom] = useState(1);
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [hoveredPoint, setHoveredPoint] = useState<number | null>(null);

  // Calculate chart dimensions and data ranges
  const margin = { top: 40, right: 60, bottom: 60, left: 80 };
  const chartWidth = width - margin.left - margin.right;
  const chartHeight = height - margin.top - margin.bottom;

  const maxPnL = Math.max(...data.map(d => d.cumulative_pnl));
  const minPnL = Math.min(...data.map(d => d.cumulative_pnl));
  const range = Math.max(Math.abs(maxPnL), Math.abs(minPnL)) || 1000;
  const centerY = margin.top + chartHeight / 2;

  // Reset zoom and pan
  const resetView = useCallback(() => {
    setZoom(1);
    setPan({ x: 0, y: 0 });
  }, []);

  // Zoom in/out functions
  const zoomIn = useCallback(() => {
    setZoom(prev => Math.min(prev * 1.5, 10));
  }, []);

  const zoomOut = useCallback(() => {
    setZoom(prev => Math.max(prev / 1.5, 0.1));
  }, []);

  // Handle mouse wheel for zooming
  const handleWheel = useCallback((event: React.WheelEvent) => {
    event.preventDefault();
    const delta = event.deltaY > 0 ? 0.9 : 1.1;
    setZoom(prev => Math.max(0.1, Math.min(10, prev * delta)));
  }, []);

  // Handle mouse events for panning
  const handleMouseDown = useCallback((event: React.MouseEvent) => {
    setIsDragging(true);
    setDragStart({ x: event.clientX - pan.x, y: event.clientY - pan.y });
  }, [pan]);

  const handleMouseMove = useCallback((event: React.MouseEvent) => {
    if (isDragging) {
      setPan({
        x: event.clientX - dragStart.x,
        y: event.clientY - dragStart.y
      });
    }
  }, [isDragging, dragStart]);

  const handleMouseUp = useCallback(() => {
    setIsDragging(false);
  }, []);

  // Generate chart elements
  const generatePath = useCallback(() => {
    if (data.length === 0) return '';
    
    const pointSpacing = (chartWidth * zoom) / Math.max(data.length - 1, 1);
    
    let pathData = '';
    data.forEach((point, index) => {
      const x = margin.left + index * pointSpacing + pan.x;
      const y = centerY - (point.cumulative_pnl / range) * (chartHeight / 2);
      
      if (index === 0) {
        pathData += `M ${x} ${y}`;
      } else {
        pathData += ` L ${x} ${y}`;
      }
    });
    
    return pathData;
  }, [data, chartWidth, chartHeight, centerY, range, zoom, pan, margin]);

  // Generate grid lines
  const generateGridLines = useCallback(() => {
    const gridLines = [];
    const ySteps = 10;
    const xSteps = Math.min(20, data.length);
    
    // Horizontal grid lines
    for (let i = 0; i <= ySteps; i++) {
      const y = margin.top + (i * chartHeight / ySteps);
      const value = range - (i * 2 * range / ySteps);
      gridLines.push(
        <g key={`h-grid-${i}`}>
          <line
            x1={margin.left}
            y1={y}
            x2={margin.left + chartWidth}
            y2={y}
            stroke="#f3f4f6"
            strokeWidth="1"
            strokeDasharray={i === ySteps / 2 ? "none" : "2,2"}
          />
          <text
            x={margin.left - 10}
            y={y + 4}
            fontSize="12"
            fill="#6b7280"
            textAnchor="end"
          >
            {formatCurrency(value)}
          </text>
        </g>
      );
    }

    // Vertical grid lines (dates)
    for (let i = 0; i <= xSteps; i++) {
      const dataIndex = Math.floor((i * (data.length - 1)) / xSteps);
      if (dataIndex < data.length) {
        const x = margin.left + (dataIndex * chartWidth * zoom / Math.max(data.length - 1, 1)) + pan.x;
        if (x >= margin.left && x <= margin.left + chartWidth) {
          gridLines.push(
            <g key={`v-grid-${i}`}>
              <line
                x1={x}
                y1={margin.top}
                x2={x}
                y2={margin.top + chartHeight}
                stroke="#f3f4f6"
                strokeWidth="1"
                strokeDasharray="2,2"
              />
              <text
                x={x}
                y={height - 10}
                fontSize="10"
                fill="#6b7280"
                textAnchor="middle"
                transform={`rotate(-45, ${x}, ${height - 10})`}
              >
                {new Date(data[dataIndex].date).toLocaleDateString()}
              </text>
            </g>
          );
        }
      }
    }

    return gridLines;
  }, [data, chartWidth, chartHeight, margin, range, zoom, pan, formatCurrency, height]);

  // Generate data points
  const generateDataPoints = useCallback(() => {
    const pointSpacing = (chartWidth * zoom) / Math.max(data.length - 1, 1);
    
    return data.map((point, index) => {
      const x = margin.left + index * pointSpacing + pan.x;
      const y = centerY - (point.cumulative_pnl / range) * (chartHeight / 2);
      
      // Only render points that are visible
      if (x < margin.left - 20 || x > margin.left + chartWidth + 20) {
        return null;
      }
      
      return (
        <circle
          key={index}
          cx={x}
          cy={y}
          r={hoveredPoint === index ? 6 : 4}
          fill={point.cumulative_pnl >= 0 ? '#10b981' : '#ef4444'}
          stroke="white"
          strokeWidth="2"
          className="chart-point"
          onMouseEnter={() => setHoveredPoint(index)}
          onMouseLeave={() => setHoveredPoint(null)}
        />
      );
    }).filter(Boolean);
  }, [data, chartWidth, chartHeight, centerY, range, zoom, pan, margin, hoveredPoint]);

  // Debug path generation
  const pathData = generatePath();
  console.log('Generated path:', pathData.substring(0, 100) + '...');
  console.log('Data points:', data.length);
  console.log('Range:', range);

  return (
    <div className="interactive-chart">
      <div className="chart-controls">
        <div className="zoom-controls">
          <button onClick={zoomIn} className="zoom-btn">
            <span>🔍+</span>
          </button>
          <button onClick={zoomOut} className="zoom-btn">
            <span>🔍-</span>
          </button>
          <button onClick={resetView} className="reset-btn">
            Reset View
          </button>
        </div>
        <div className="chart-info">
          <span>Zoom: {(zoom * 100).toFixed(0)}%</span>
          <span>Points: {data.length}</span>
          <span>Range: {formatCurrency(range)}</span>
        </div>
      </div>

      <div className="chart-container">
        <svg
          ref={svgRef}
          width={width}
          height={height}
          viewBox={`0 0 ${width} ${height}`}
          onWheel={handleWheel}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onMouseLeave={handleMouseUp}
          style={{ cursor: isDragging ? 'grabbing' : 'grab' }}
        >
          {/* Background */}
          <rect
            width={width}
            height={height}
            fill="white"
            stroke="#e5e7eb"
            strokeWidth="1"
          />

          {/* Grid lines */}
          {generateGridLines()}

          {/* Chart area clipping */}
          <defs>
            <clipPath id="chart-area">
              <rect
                x={margin.left}
                y={margin.top}
                width={chartWidth}
                height={chartHeight}
              />
            </clipPath>
          </defs>

          {/* P&L line */}
          <g clipPath="url(#chart-area)">
            {data.length > 0 && (
              <>
                {/* Main line */}
                <path
                  d={generatePath()}
                  fill="none"
                  stroke={data[data.length - 1]?.cumulative_pnl >= 0 ? '#10b981' : '#ef4444'}
                  strokeWidth="4"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  opacity="1"
                />
                {/* Shadow line for better visibility */}
                <path
                  d={generatePath()}
                  fill="none"
                  stroke="rgba(0, 0, 0, 0.1)"
                  strokeWidth="6"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  opacity="0.5"
                />
              </>
            )}

            {/* Data points */}
            {generateDataPoints()}
          </g>

          {/* Axes */}
          <line
            x1={margin.left}
            y1={margin.top}
            x2={margin.left}
            y2={margin.top + chartHeight}
            stroke="#374151"
            strokeWidth="2"
          />
          <line
            x1={margin.left}
            y1={margin.top + chartHeight}
            x2={margin.left + chartWidth}
            y2={margin.top + chartHeight}
            stroke="#374151"
            strokeWidth="2"
          />

          {/* Chart title */}
          <text
            x={width / 2}
            y={25}
            fontSize="16"
            fontWeight="600"
            fill="#374151"
            textAnchor="middle"
          >
            Cumulative P&L Over Time
          </text>

          {/* Tooltip */}
          {hoveredPoint !== null && data[hoveredPoint] && (
            <g>
              <rect
                x={margin.left + (hoveredPoint * chartWidth * zoom / Math.max(data.length - 1, 1)) + pan.x + 10}
                y={centerY - (data[hoveredPoint].cumulative_pnl / range) * (chartHeight / 2) - 40}
                width="200"
                height="60"
                fill="rgba(0, 0, 0, 0.9)"
                rx="4"
                stroke="rgba(255, 255, 255, 0.2)"
                strokeWidth="1"
              />
              <text
                x={margin.left + (hoveredPoint * chartWidth * zoom / Math.max(data.length - 1, 1)) + pan.x + 20}
                y={centerY - (data[hoveredPoint].cumulative_pnl / range) * (chartHeight / 2) - 20}
                fontSize="12"
                fill="white"
                fontWeight="500"
              >
                Date: {data[hoveredPoint].date}
              </text>
              <text
                x={margin.left + (hoveredPoint * chartWidth * zoom / Math.max(data.length - 1, 1)) + pan.x + 20}
                y={centerY - (data[hoveredPoint].cumulative_pnl / range) * (chartHeight / 2) - 5}
                fontSize="12"
                fill="white"
                fontWeight="500"
              >
                P&L: {formatCurrency(data[hoveredPoint].cumulative_pnl)}
              </text>
            </g>
          )}
        </svg>
      </div>

      <div className="chart-instructions">
        <small>
          💡 Use mouse wheel to zoom, click and drag to pan, or use the controls above
        </small>
      </div>
    </div>
  );
};

export default InteractiveChart;
